contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 salt) public {
        require(!c.hasRole(c.PROPOSER_ROLE(), address(this)));
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        require(c.hasRole(c.PROPOSER_ROLE(), address(this)));

        uint256 delay = c.getMinDelay() + 1;
        c.schedule(address(this), 0, "", bytes32(0), salt, delay);

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);
        bool isReady = c.isOperationReady(id);

        assert(isOp && isPending && !isReady && ts > block.timestamp);
    }

    receive() external payable {}
}

