contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address target1,
        address target2,
        uint256 value1,
        uint256 value2,
        bytes calldata data1,
        bytes calldata data2,
        bytes32 predecessor1,
        bytes32 predecessor2,
        bytes32 salt1,
        bytes32 salt2
    ) public payable {
        require(
            target1 != target2 ||
            value1 != value2 ||
            keccak256(data1) != keccak256(data2) ||
            predecessor1 != predecessor2 ||
            salt1 != salt2,
            "precondition: single components differ"
        );

        bytes32 h1 = c.hashOperation(target1, value1, data1, predecessor1, salt1);
        bytes32 h2 = c.hashOperation(target2, value2, data2, predecessor2, salt2);

        address[] memory targets = new address[](1);
        uint256[] memory values = new uint256[](1);
        bytes[] memory datas = new bytes[](1);
        targets[0] = target1;
        values[0] = value1;
        datas[0] = data1;

        bytes32 hb1 = c.hashOperationBatch(targets, values, datas, predecessor1, salt1);
        bytes32 hb2 = c.hashOperationBatch(targets, values, datas, predecessor1, salt2);

        assert(
            (h1 != h2 || keccak256(abi.encode(h1, h2)) == keccak256(abi.encode(h1, h2))) &&
            hb1 != hb2
        );
    }

    receive() external payable {}
}
